import { PANERELAY_PROTOCOL_VERSION } from './constants.js';
import { isAutomationActivitySnapshotMessage, isAutomationActivityUpdatedMessage, isControlSessionChangedMessage, } from './control-activity.js';
import { isBrowserFetchCancelMessage, isBrowserFetchPermissionCancelMessage, isBrowserFetchPermissionRequestMessage, isBrowserFetchPermissionResultMessage, isBrowserFetchRequestMessage, isBrowserFetchResultMessage, } from './browser-fetch.js';
import { comparePanerelayReleaseVersions, isPanerelayChromiumBuildVersion, isPanerelayReleaseVersion, } from './release-version.js';
export * from './constants.js';
export * from './browser-fetch.js';
export * from './cli-adapter.js';
export * from './cdp-bootstrap.js';
export * from './conversation-target.js';
export * from './control-activity.js';
export * from './native-transfer.js';
export * from './release-version.js';
export const HOST_UPDATE_DETAIL_MAX_LENGTH = 240;
export function nativeHostManualUpdateCommand(targetVersion) {
    if (!isPanerelayReleaseVersion(targetVersion)) {
        throw new Error('A manual Native Host update requires a valid Panerelay release');
    }
    return `npx --yes @panerelay/setup@${targetVersion} update --yes`;
}
export function isAutomationEngineId(value) {
    return value === 'agent-browser' || value === 'browser-use' || value === 'playwright';
}
export function isCdpControlUpdatedMessage(value) {
    if (!value || typeof value !== 'object')
        return false;
    const candidate = value;
    return (hasOnlyKeys(candidate, ['type', 'protocol', 'targetId', 'engine']) &&
        candidate.type === 'cdp.control.updated' &&
        candidate.protocol === PANERELAY_PROTOCOL_VERSION &&
        typeof candidate.targetId === 'string' &&
        candidate.targetId.length > 0 &&
        candidate.targetId.length <= 256 &&
        (candidate.engine === null || isAutomationEngineId(candidate.engine)));
}
export const CONVERSATION_MAX_IMAGES = 4;
export const CONVERSATION_MAX_IMAGE_BYTES = 10 * 1024 * 1024;
export const CONVERSATION_MAX_TOTAL_IMAGE_BYTES = 20 * 1024 * 1024;
export const CONVERSATION_IMAGE_MIME_TYPES = [
    'image/png',
    'image/jpeg',
    'image/webp',
    'image/gif',
];
function hasOnlyKeys(candidate, allowed) {
    return Object.keys(candidate).every(key => allowed.includes(key));
}
function isHostUpdateError(value) {
    return [
        'lock-timeout',
        'network',
        'package-unavailable',
        'setup-failed',
        'timeout',
        'verification-failed',
        'unknown',
    ].includes(value);
}
function isHostUpdateStatusMessage(value) {
    if (value.protocol !== PANERELAY_PROTOCOL_VERSION ||
        value.type !== 'host.update.status' ||
        !isPanerelayReleaseVersion(value.hostVersion) ||
        typeof value.state !== 'string' ||
        typeof value.retryAvailable !== 'boolean') {
        return false;
    }
    if (value.state === 'incompatible') {
        if (!hasOnlyKeys(value, [
            'type',
            'protocol',
            'state',
            'hostVersion',
            'targetVersion',
            'retryAvailable',
            'reason',
        ]) ||
            value.retryAvailable !== false ||
            !['invalid-extension-release', 'newer-host'].includes(value.reason)) {
            return false;
        }
        if (value.reason === 'invalid-extension-release')
            return value.targetVersion === undefined;
        return (isPanerelayReleaseVersion(value.targetVersion) &&
            comparePanerelayReleaseVersions(value.hostVersion, value.targetVersion) > 0);
    }
    if (!isPanerelayReleaseVersion(value.targetVersion))
        return false;
    if (value.state === 'failed') {
        return (hasOnlyKeys(value, [
            'type',
            'protocol',
            'state',
            'hostVersion',
            'targetVersion',
            'retryAvailable',
            'error',
            'detail',
            'manualCommand',
        ]) &&
            value.retryAvailable === true &&
            isHostUpdateError(value.error) &&
            (value.detail === undefined ||
                (typeof value.detail === 'string' &&
                    value.detail.length <= HOST_UPDATE_DETAIL_MAX_LENGTH)) &&
            value.manualCommand === nativeHostManualUpdateCommand(value.targetVersion) &&
            comparePanerelayReleaseVersions(value.hostVersion, value.targetVersion) < 0);
    }
    return (['required', 'updating', 'restart-pending'].includes(value.state) &&
        hasOnlyKeys(value, [
            'type',
            'protocol',
            'state',
            'hostVersion',
            'targetVersion',
            'retryAvailable',
        ]) &&
        value.retryAvailable === false &&
        comparePanerelayReleaseVersions(value.hostVersion, value.targetVersion) < 0);
}
export function isExtensionToHostMessage(value) {
    if (!value || typeof value !== 'object')
        return false;
    const candidate = value;
    if (candidate.protocol !== PANERELAY_PROTOCOL_VERSION || typeof candidate.type !== 'string') {
        return false;
    }
    if (candidate.type === 'browser.register') {
        return (hasOnlyKeys(candidate, [
            'type',
            'protocol',
            'browserId',
            'browserName',
            'extensionId',
            'releaseVersion',
            'buildVersion',
            'checkHostUpdate',
            'browserFamily',
            'capabilities',
        ]) &&
            typeof candidate.browserId === 'string' &&
            typeof candidate.browserName === 'string' &&
            typeof candidate.extensionId === 'string' &&
            isPanerelayReleaseVersion(candidate.releaseVersion) &&
            isPanerelayChromiumBuildVersion(candidate.buildVersion) &&
            typeof candidate.checkHostUpdate === 'boolean' &&
            (candidate.browserFamily === undefined ||
                ['chrome', 'chromium', 'edge', 'unknown'].includes(candidate.browserFamily)) &&
            (candidate.capabilities === undefined ||
                (typeof candidate.capabilities === 'object' &&
                    candidate.capabilities !== null &&
                    hasOnlyKeys(candidate.capabilities, [
                        'cdpRelay',
                        'browserFetch',
                    ]) &&
                    typeof candidate.capabilities.cdpRelay === 'boolean' &&
                    (candidate.capabilities.browserFetch === undefined ||
                        typeof candidate.capabilities.browserFetch === 'boolean'))));
    }
    if (candidate.type === 'host.update.retry') {
        return hasOnlyKeys(candidate, ['type', 'protocol']);
    }
    if (candidate.type === 'fetch.result')
        return isBrowserFetchResultMessage(value);
    if (candidate.type === 'fetch.permission.result') {
        return isBrowserFetchPermissionResultMessage(value);
    }
    return [
        'cdp.target.result',
        'cdp.target.event',
        'cdp.attached',
        'cdp.result',
        'cdp.event',
        'cdp.detached',
        'agent.request',
        'integration.request',
    ].includes(candidate.type);
}
export function isHostToExtensionMessage(value) {
    if (!value || typeof value !== 'object')
        return false;
    const candidate = value;
    if (candidate.type === 'control.session.changed') {
        return isControlSessionChangedMessage(value);
    }
    if (candidate.type === 'control.activity.snapshot') {
        return isAutomationActivitySnapshotMessage(value);
    }
    if (candidate.type === 'control.activity.updated') {
        return isAutomationActivityUpdatedMessage(value);
    }
    if (candidate.type === 'cdp.control.updated') {
        return isCdpControlUpdatedMessage(value);
    }
    if (candidate.type === 'host.update.status') {
        return isHostUpdateStatusMessage(candidate);
    }
    if (candidate.type === 'browser.registered') {
        return (candidate.protocol === PANERELAY_PROTOCOL_VERSION &&
            typeof candidate.browserId === 'string' &&
            isPanerelayReleaseVersion(candidate.hostVersion));
    }
    if (candidate.type === 'fetch.request')
        return isBrowserFetchRequestMessage(value);
    if (candidate.type === 'fetch.cancel')
        return isBrowserFetchCancelMessage(value);
    if (candidate.type === 'fetch.permission.cancel') {
        return isBrowserFetchPermissionCancelMessage(value);
    }
    if (candidate.type === 'fetch.permission.request') {
        return isBrowserFetchPermissionRequestMessage(value);
    }
    return (candidate.protocol === PANERELAY_PROTOCOL_VERSION &&
        typeof candidate.type === 'string' &&
        [
            'cdp.target.request',
            'cdp.attach',
            'cdp.command',
            'cdp.detach',
            'agent.response',
            'integration.response',
            'conversation.event',
        ].includes(candidate.type));
}
